CREATE OR REPLACE FUNCTION public.admin_update_booking_status(p_booking_id uuid, p_new_status character varying, p_cancellation_reason text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_slot_id uuid;
  v_current_status varchar;
BEGIN
  -- Verify caller is Admin
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Access denied: Admin privileges required.' USING ERRCODE = '42501';
  END IF;

  -- Get current booking details
  SELECT status, slot_id INTO v_current_status, v_slot_id
  FROM public.consultation_bookings
  WHERE id = p_booking_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found with ID %', p_booking_id USING ERRCODE = 'P0002';
  END IF;

  -- Update booking record
  UPDATE public.consultation_bookings
  SET 
    status = p_new_status,
    cancellation_reason = CASE 
      WHEN p_cancellation_reason IS NOT NULL THEN p_cancellation_reason 
      ELSE cancellation_reason 
    END,
    updated_at = now()
  WHERE id = p_booking_id;

  -- If status changed to Cancelled, unbook the corresponding slot
  IF p_new_status = 'Cancelled' AND v_slot_id IS NOT NULL THEN
    UPDATE public.consultation_slots
    SET is_booked = false
    WHERE id = v_slot_id;
  END IF;

  -- Audit log entry
  INSERT INTO public.admin_audit_log (
    admin_id,
    action,
    target_table,
    target_id,
    details
  ) VALUES (
    auth.uid(),
    'update_booking_status',
    'consultation_bookings',
    p_booking_id,
    jsonb_build_object(
      'previous_status', v_current_status,
      'new_status', p_new_status,
      'cancellation_reason', p_cancellation_reason
    )
  );

  RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.approve_expert_application(p_application_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id uuid;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  SELECT user_id INTO v_user_id FROM public.expert_applications WHERE id = p_application_id;

  UPDATE public.expert_applications SET status = 'Approved' WHERE id = p_application_id;
  INSERT INTO public.experts (user_id, verified_date) VALUES (v_user_id, current_date)
    ON CONFLICT (user_id) DO NOTHING;
  UPDATE public.profiles SET role = 'Expert' WHERE id = v_user_id;

  -- Notification with related_id pointing to profiles.id
  INSERT INTO public.notifications (user_id, type, message, related_id)
    VALUES (v_user_id, 'announcement', 'Congratulations! Your Expert application has been approved.', v_user_id);

  INSERT INTO public.admin_audit_log (admin_id, action, target_table, target_id)
    VALUES (auth.uid(), 'approve_expert', 'expert_applications', p_application_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.approve_expert_resignation(p_resignation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare v_user_id uuid;
begin
  if not public.is_admin() then raise exception 'not authorized'; end if;
  select user_id into v_user_id from public.expert_resignations where id = p_resignation_id;
  update public.expert_resignations set status = 'Approved' where id = p_resignation_id;
  perform public.demote_expert(v_user_id);
end;
$function$
;

