CREATE OR REPLACE FUNCTION public.handle_comment_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if (TG_OP = 'INSERT') then
    update public.posts
    set comment_count = comment_count + 1
    where id = new.post_id;
    return new;
  elsif (TG_OP = 'DELETE') then
    update public.posts
    set comment_count = comment_count - 1
    where id = old.post_id;
    return old;
  end if;
  return null;
end;
$function$
;

