CREATE OR REPLACE FUNCTION public.resolve_report(p_report_id uuid, p_action moderation_action, p_delete_content boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_post_id uuid;
begin
  if not public.is_admin() then raise exception 'not authorized'; end if;

  select post_id into v_post_id from public.reports where id = p_report_id;

  update public.reports set status = 'Resolved' where id = p_report_id;
  insert into public.admin_moderation (admin_id, content_type, post_id, action)
    values (auth.uid(), 'Post', v_post_id, p_action);

  if p_delete_content and v_post_id is not null then
    delete from public.posts where id = v_post_id;
  end if;

  insert into public.admin_audit_log (admin_id, action, target_table, target_id)
    values (auth.uid(), 'resolve_report', 'reports', p_report_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.send_broadcast(p_title text, p_message text, p_image_path text DEFAULT NULL::text, p_target_role user_role DEFAULT NULL::user_role, p_target_user_id uuid DEFAULT NULL::uuid, p_action_type text DEFAULT 'dismissible'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_broadcast_id uuid;
  v_count int;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  INSERT INTO public.broadcasts (title, message, image_path, target_role, target_user_id, action_type, sent_by)
    VALUES (p_title, p_message, p_image_path, p_target_role, p_target_user_id, p_action_type, auth.uid())
    RETURNING id INTO v_broadcast_id;

  INSERT INTO public.notifications (user_id, type, message, related_id)
  SELECT id, 'announcement', p_message, v_broadcast_id FROM public.profiles
  WHERE (p_target_user_id IS NOT NULL AND id = p_target_user_id)
     OR (p_target_user_id IS NULL AND (p_target_role IS NULL OR role = p_target_role));

  GET DIAGNOSTICS v_count = ROW_COUNT;
  UPDATE public.broadcasts SET recipient_count = v_count WHERE id = v_broadcast_id;
  RETURN v_broadcast_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.send_broadcast(p_title text, p_message text, p_target_role user_role DEFAULT NULL::user_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_broadcast_id uuid;
  v_count int;
begin
  if not public.is_admin() then raise exception 'not authorized'; end if;

  insert into public.broadcasts (title, message, target_role, sent_by)
    values (p_title, p_message, p_target_role, auth.uid())
    returning id into v_broadcast_id;

  insert into public.notifications (user_id, type, message)
  select id, 'announcement', p_message from public.profiles
  where p_target_role is null or role = p_target_role;

  get diagnostics v_count = row_count;
  update public.broadcasts set recipient_count = v_count where id = v_broadcast_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_follower_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.profiles SET follower_count = follower_count + 1 WHERE id = NEW.following_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.profiles SET follower_count = follower_count - 1 WHERE id = OLD.following_id;
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE TRIGGER on_comment_change AFTER INSERT OR DELETE ON public.comments FOR EACH ROW EXECUTE FUNCTION handle_comment_count();

CREATE TRIGGER on_community_member_change AFTER INSERT OR DELETE ON public.community_members FOR EACH ROW EXECUTE FUNCTION handle_community_member_count();

CREATE TRIGGER followers_count_trigger AFTER INSERT OR DELETE ON public.followers FOR EACH ROW EXECUTE FUNCTION update_follower_count();

CREATE TRIGGER on_like_change AFTER INSERT OR DELETE ON public.likes FOR EACH ROW EXECUTE FUNCTION handle_like_count();

CREATE TRIGGER on_post_change AFTER INSERT OR DELETE ON public.posts FOR EACH ROW EXECUTE FUNCTION handle_profile_post_count();

CREATE TRIGGER on_profile_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION handle_update_timestamp();

CREATE TRIGGER on_review_change AFTER INSERT OR DELETE OR UPDATE ON public.reviews FOR EACH ROW EXECUTE FUNCTION handle_review_rating();

CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();

