  with check (((bucket_id = 'news-images'::text) AND is_admin()));

create policy "Private buckets are readable by owner and admins" on storage.objects as permissive for SELECT to public
  using (((bucket_id = ANY (ARRAY['expert-cvs'::text, 'disease-images'::text])) AND (((auth.uid())::text = path_tokens[1]) OR is_admin())));

create policy "Public buckets are readable by everyone" on storage.objects as permissive for SELECT to public
  using ((bucket_id = ANY (ARRAY['avatars'::text, 'post-images'::text, 'product-images'::text, 'community-images'::text, 'news-images'::text])));

