create policy "Users can upload their own files" on storage.objects as permissive for INSERT to public
  with check (((bucket_id = ANY (ARRAY['avatars'::text, 'post-images'::text, 'product-images'::text, 'community-images'::text, 'expert-cvs'::text, 'disease-images'::text])) AND ((auth.uid())::text = path_tokens[1])));

